import React, { useState } from 'react';

function App(): JSX.Element {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [authorizationCode, setAuthorizationCode] = useState<string>('');

  const generateCodeVerifier = (): string => {
    const array = new Uint8Array(32);
    window.crypto.getRandomValues(array);
    return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
  };

  const generateCodeChallenge = async (verifier: string): Promise<string> => {
    const encoder = new TextEncoder();
    const data = encoder.encode(verifier);
    const hash = await window.crypto.subtle.digest('SHA-256', data);
    return btoa(String.fromCharCode(...new Uint8Array(hash)))
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=+$/, '');
  };

  const handleLogin = async (): Promise<void> => {
    const verifier = generateCodeVerifier();
    const challenge = await generateCodeChallenge(verifier);
    // In a real app, you would store the verifier securely (e.g., sessionStorage)
    sessionStorage.setItem('code_verifier', verifier);

    const authUrl = `https://authorization-server.com/authorize?response_type=code&client_id=your-client-id&redirect_uri=${encodeURIComponent(window.location.origin)}&code_challenge=${challenge}&code_challenge_method=S256`;
    window.location.href = authUrl;
  };

  const exchangeCodeForToken = async (code: string): Promise<void> => {
    const verifier = sessionStorage.getItem('code_verifier');
    if (!verifier) return;

    const response = await fetch('https://authorization-server.com/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: 'your-client-id',
        redirect_uri: window.location.origin,
        code,
        code_verifier: verifier
      })
    });

    if (response.ok) {
      const data = await response.json();
      console.log('Access token:', data.access_token);
      setIsAuthenticated(true);
    }
  };

  return (
    <div className="container">
      <h1>OAuth2 PKCE Flow Demo</h1>
      <button onClick={handleLogin}>Login with OAuth2</button>

    </div>
  );
}

